const baseline = $('Evaluate request').first().json;
const content = (typeof $json.output === 'string' && $json.output.trim()) ? $json.output.trim() : null;
const failed = !content || Boolean($json.error);
const manualSmokeTest = $('Manual Trigger - Safe Smoke Test').isExecuted;

// A local Manual Trigger is an acceptance test, not a graceful-degradation path.
// Fail the execution if the provider/model did not return non-empty text so the
// Windows updater cannot record a fallback result as an OpenAI connection pass.
if (manualSmokeTest && failed) {
  throw new Error('SMARTNET_OPENAI_SMOKE_TEST_FAILED: OpenAI returned no usable model output.');
}

const result = {
  ...baseline,
  ai_advisory: {
    provider: 'OpenAI',
    model: 'gpt-6-luna',
    status: failed ? 'unavailable' : 'completed',
    content: content,
    note: failed
      ? 'تعذر الحصول على تحليل النموذج؛ تم الاحتفاظ بنتيجة التحقق الحتمية.'
      : 'هذه توصية تفسيرية فقط ولا تغيّر نتيجة التحقق الحتمية.',
  },
  execution_authority: 'read_only_advisory',
  side_effects_performed: false,
};
if (manualSmokeTest) {
  result.smoke_test_marker = 'SMARTNET_OPENAI_SMOKE_TEST_PASS';
}
return [{ json: result }];
